<template><div class="system-page"><div class="page-head"><div><h1>操作日志</h1><p>查看注册审核、用户、角色、权限、安全设置等关键动作。</p></div><el-button @click="load">刷新</el-button></div><div class="card toolbar"><el-input v-model="filters.username" placeholder="操作人" style="width:160px" clearable/><el-input v-model="filters.module" placeholder="模块" style="width:160px" clearable/><el-input v-model="filters.action" placeholder="动作" style="width:180px" clearable/><el-button type="primary" @click="load">查询</el-button></div><div class="card"><el-table :data="rows"><el-table-column prop="created_at" label="时间" width="180"/><el-table-column prop="username" label="操作人" width="120"/><el-table-column prop="module" label="模块" width="120"/><el-table-column prop="action" label="动作" width="180"/><el-table-column prop="target_type" label="对象" width="120"/><el-table-column prop="target_id" label="对象ID" width="160"/><el-table-column prop="ip" label="IP" width="140"/><el-table-column label="详情"><template #default="{row}"><el-button link @click="detail=row;visible=true">查看</el-button></template></el-table-column></el-table><el-pagination style="margin-top:16px" layout="total, prev, pager, next" :total="total" v-model:current-page="filters.page" :page-size="filters.page_size" @current-change="load"/></div><el-dialog v-model="visible" title="日志详情" width="720px"><pre class="jsonbox">{{JSON.stringify(detail,null,2)}}</pre></el-dialog></div></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{systemApi}from'@/api/system';const rows=ref<any[]>([]),total=ref(0),visible=ref(false),detail=ref<any>({});const filters=reactive({page:1,page_size:20,username:'',module:'',action:''});async function load(){const r=await systemApi.getOperationLogs(filters);rows.value=r.data.data.items||[];total.value=r.data.data.total||0}onMounted(load)</script>
<style scoped>.system-page{padding:24px;background:#f6f8fb;min-height:100%}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head h1{margin:0;color:#0f172a;font-size:26px}.page-head p{margin:8px 0 0;color:#64748b}.card{background:#fff;border:1px solid #e5eaf2;border-radius:14px;padding:18px;margin-bottom:16px;box-shadow:0 8px 24px rgba(15,23,42,.04)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.stat{background:#fff;border:1px solid #e5eaf2;border-radius:14px;padding:18px}.stat b{font-size:28px;color:#0f172a}.stat span{display:block;color:#64748b;margin-top:6px}.layout2{display:grid;grid-template-columns:360px 1fr;gap:16px}.muted{color:#94a3b8;font-size:12px}.jsonbox{max-height:280px;overflow:auto;background:#0f172a;color:#e2e8f0;padding:12px;border-radius:10px;font-size:12px;white-space:pre-wrap}@media(max-width:1100px){.layout2{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style>
